// GENERATED BY AI TO ASSIST IN DEMO SETUP
//
// writes a standalone copy of an html page with compiled LANES programs inside it
//
// usage: node tools/embed_wasm.mjs <template.html> <output.html> <name>=<file>...
//
// the template must contain the placeholder "__LANES_PROGRAMS__" (with the quotes)
// exactly once. it is replaced with an object mapping each name to the file's
// contents: base64 for a .wasm, plain text for anything else (such as the .lanes
// source, for the page to show). the page can then instantiate the programs
// without fetching files (which browsers block for file:// pages)

import { readFile, writeFile } from "node:fs/promises";

const PLACEHOLDER = '"__LANES_PROGRAMS__"';

const [templatePath, outputPath, ...programArguments] = process.argv.slice(2);
if (!templatePath || !outputPath || programArguments.length === 0) {
    console.error("usage: node tools/embed_wasm.mjs <template.html> <output.html> <name>=<file>...");
    process.exit(2);
}

const template = await readFile(templatePath, "utf8");

const count = template.split(PLACEHOLDER).length - 1;
if (count !== 1) {
    console.error(`${templatePath}: expected the placeholder ${PLACEHOLDER} once, found it ${count} times`);
    process.exit(1);
}

const programs = {};
let totalBytes = 0;
for (const argument of programArguments) {
    const separator = argument.indexOf("=");
    if (separator <= 0) {
        console.error(`expected <name>=<file>, got '${argument}'`);
        process.exit(2);
    }
    const path = argument.slice(separator + 1);
    const bytes = await readFile(path);
    programs[argument.slice(0, separator)] = path.endsWith(".wasm") ? bytes.toString("base64") : bytes.toString("utf8");
    totalBytes += bytes.length;
}

// "</" is escaped so an embedded source containing "</script>" cannot end the page's
// script early. a function replacement, so `$` in the text is never treated as a pattern
const embedded = JSON.stringify(programs, null, 4).replaceAll("</", "<\\/");
const output = template.replace(PLACEHOLDER, () => embedded);
await writeFile(outputPath, output);

console.log(`\nwrote ${outputPath} (${programArguments.length} files, ${totalBytes} bytes embedded). Open it in your browser!\n`);